$pdo=mg_db();function ccdv4_assert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$tables=mg_creator_campaign_deliverable_required_tables();$placeholders=implode(',',array_fill(0,count($tables),'?'));$stmt=$pdo->prepare("SELECT table_name FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ({$placeholders})");$stmt->execute($tables);ccdv4_assert(count($stmt->fetchAll(PDO::FETCH_COLUMN)?:[])===count($tables),'Phase 4 tables are incomplete.');
