$columns=['campaign_id','participant_id','campaign_deliverable_id','agreement_version_id','creator_user_id','status','lock_version'];$p=implode(',',array_fill(0,count($columns),'?'));$stmt=$pdo->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='creator_campaign_participant_deliverables' AND column_name IN ({$p})");$stmt->execute($columns);ccdv4_assert((int)$stmt->fetchColumn()===count($columns),'Assignment integrity columns are incomplete.');
$stmt=$pdo->query("SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='creator_campaign_participant_deliverables' AND index_name='uq_cc_participant_deliverable_assignment' AND non_unique=0");ccdv4_assert((int)$stmt->fetchColumn()>=1,'One assignment per participant and deliverable is not enforced.');
$stmt=$pdo->query("SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='creator_campaign_submission_revisions' AND index_name='uq_cc_submission_revision_number' AND non_unique=0");ccdv4_assert((int)$stmt->fetchColumn()>=1,'Submission revision numbers are not immutable and unique.');
$stmt=$pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('creator_campaign_compensation_rules','creator_campaign_earning_events','creator_campaign_budget_ledger','creator_campaign_payouts','creator_campaign_disputes')");ccdv4_assert((int)$stmt->fetchColumn()===0,'Financial or dispute tables were created prematurely.');
echo json_encode(['ok'=>true,'tables'=>count($tables),'permissions'=>count($permissions),'agreement_version_assignments'=>true,'immutable_revisions'=>true,'publication_proof'=>true,'phase5_compatible'=>true,'later_phase_tables'=>0],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR).PHP_EOL;
